1	import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
2	import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
3	
4	const ALLOWED_ORIGINS = [
5	  Deno.env.get("APP_URL") || "https://rankora.co",
6	  "https://www.rankora.co",
7	  "http://localhost:8080",
8	  "http://localhost:5173",
9	];
10	
11	function getCorsOrigin(req: Request): string {
12	  const origin = req.headers.get("origin") || "";
13	  return ALLOWED_ORIGINS.includes(origin) ? origin : ALLOWED_ORIGINS[0];
14	}
15	
16	const OPENAI_API_KEY = Deno.env.get("OPENAI_API_KEY")!;
17	const SUPABASE_URL = Deno.env.get("SUPABASE_URL")!;
18	const SUPABASE_SERVICE_ROLE_KEY = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
19	
20	serve(async (req) => {
21	  const corsHeaders = {
22	    "Access-Control-Allow-Origin": getCorsOrigin(req),
23	    "Access-Control-Allow-Headers":
24	      "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
25	  };
26	  if (req.method === "OPTIONS") return new Response(null, { headers: corsHeaders });
27	
28	  try {
29	    // Auth check
30	    const authHeader = req.headers.get("Authorization");
31	    if (!authHeader) throw new Error("No auth header");
32	
33	    const token = authHeader.replace("Bearer ", "");
34	    const anonKey = Deno.env.get("SUPABASE_PUBLISHABLE_KEY") || Deno.env.get("SUPABASE_ANON_KEY")!;
35	    const supabaseUser = createClient(SUPABASE_URL, anonKey, {
36	      global: { headers: { Authorization: authHeader } },
37	    });
38	    const { data: claimsData, error: claimsError } = await supabaseUser.auth.getClaims(token);
39	    if (claimsError || !claimsData?.claims) throw new Error("Unauthorized");
40	    const user = { id: claimsData.claims.sub as string };
41	
42	    const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);
43	
44	    const { job_id } = await req.json();
45	    if (!job_id) throw new Error("Missing job_id");
46	
47	    // Verify ownership and fetch JD
48	    const { data: job } = await supabase
49	      .from("jobs")
50	      .select("id, job_description, user_id")
51	      .eq("id", job_id)
52	      .single();
53	
54	    if (!job) throw new Error("Job not found");
55	    if (job.user_id !== user.id) throw new Error("Unauthorized");
56	
57	    const jdText: string = job.job_description || "";
58	
59	    // Guard: refuse if JD is too short
60	    if (jdText.trim().length < 50) {
61	      throw new Error("Job description is too short to rewrite (minimum 50 characters).");
62	    }
63	
64	    // Deduct 1 credit before calling OpenAI
65	    const { data: creditOk } = await supabase.rpc("deduct_credits", {
66	      _user_id: user.id,
67	      _job_id: job_id,
68	      _amount: 1,
69	    });
70	    if (!creditOk) throw new Error("Insufficient credits");
71	
72	    // Single LLM call: rewrite + score the original JD
73	    const systemPrompt = `You are an expert technical recruiter and job description specialist. Your task is to:
74	1. Rewrite the provided job description for maximum clarity, ATS optimization, and inclusive language.
75	2. Score the ORIGINAL job description (before rewriting) on 4 dimensions.
76	3. Identify important keywords and whether they appear in the original.
77	
78	REWRITING GUIDELINES:
79	- Use clear, concise language. Avoid jargon unless it is a required technical term.
80	- Structure with clear sections: Role Summary, Responsibilities, Requirements (Must-Have), Nice to Have, and Benefits (if present).
81	- Use inclusive language: avoid gendered words, age indicators, or unnecessarily exclusionary phrasing.
82	- Ensure ATS-friendly formatting: use standard section headers, bullet points, and spell out acronyms on first use.
83	- Preserve all original requirements — do not add or remove skills/qualifications.
84	- Keep the same general tone (technical, professional, etc.) as the original.
85	
86	SCORING GUIDELINES (score the ORIGINAL JD, 0–100 each):
87	- clarity: How clearly written and structured is the JD? (0=incomprehensible, 100=extremely clear)
88	- keywords: How well does the JD include relevant industry keywords for ATS? (0=almost none, 100=comprehensive)
89	- ats_fit: How well formatted is the JD for ATS systems? (0=very poor, 100=excellent)
90	- inclusivity: How inclusive and bias-free is the language? (0=highly exclusive, 100=fully inclusive)
91	
92	MISSING KEYWORDS: List 8–12 important keywords/skills. For each, indicate if it was "detected" in the original JD or "missing".
93	
94	Return ONLY valid JSON with this exact structure:
95	{
96	  "rewritten_jd": "...",
97	  "quality_score": {
98	    "overall": <number 0-100, average of the 4 scores>,
99	    "clarity": <number 0-100>,
100	    "keywords": <number 0-100>,
101	    "ats_fit": <number 0-100>,
102	    "inclusivity": <number 0-100>
103	  },
104	  "missing_keywords": [
105	    { "keyword": "...", "status": "missing" | "detected" }
106	  ]
107	}`;
108	
109	    const response = await fetch("https://api.openai.com/v1/chat/completions", {
110	      method: "POST",
111	      headers: {
112	        Authorization: `Bearer ${OPENAI_API_KEY}`,
113	        "Content-Type": "application/json",
114	      },
115	      body: JSON.stringify({
116	        model: "gpt-4o",
117	        messages: [
118	          { role: "system", content: systemPrompt },
119	          { role: "user", content: `JOB DESCRIPTION TO ANALYZE AND REWRITE:\n\n${jdText.slice(0, 8000)}` },
120	        ],
121	        response_format: { type: "json_object" },
122	        temperature: 0.3,
123	      }),
124	    });
125	
126	    if (!response.ok) {
127	      const errBody = await response.text();
128	      throw new Error(`OpenAI API error ${response.status}: ${errBody.slice(0, 200)}`);
129	    }
130	
131	    const aiData = await response.json();
132	    const content = aiData.choices?.[0]?.message?.content;
133	    if (!content) throw new Error("OpenAI returned empty response");
134	
135	    const parsed = JSON.parse(content);
136	
137	    if (!parsed.rewritten_jd || !parsed.quality_score || !Array.isArray(parsed.missing_keywords)) {
138	      throw new Error("Unexpected response structure from OpenAI");
139	    }
140	
141	    // Store results in jobs table
142	    const { error: updateError } = await supabase
143	      .from("jobs")
144	      .update({
145	        rewritten_jd: parsed.rewritten_jd,
146	        jd_quality_score: parsed.quality_score,
147	      } as any)
148	      .eq("id", job_id);
149	
150	    if (updateError) throw new Error(`Failed to save rewrite results: ${updateError.message}`);
151	
152	    console.log(`JD rewrite complete for job ${job_id}`);
153	
154	    return new Response(
155	      JSON.stringify({
156	        success: true,
157	        rewritten_jd: parsed.rewritten_jd,
158	        quality_score: parsed.quality_score,
159	        missing_keywords: parsed.missing_keywords,
160	      }),
161	      { headers: { ...corsHeaders, "Content-Type": "application/json" } }
162	    );
163	  } catch (err) {
164	    console.error("rewrite-jd error:", err);
165	    return new Response(
166	      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
167	      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } }
168	    );
169	  }
170	});
171	
